#![allow(clippy::excessive_precision)]
//! Golden-parity tests for the reference's manual erosion passes
//! (`PARITY_TESTING.md`). Fixtures were extracted from
//! `reference/Cartalith Gen1 v2.10.html` by a transient Node
//! `vm.runInContext` harness running the reference's own source verbatim —
//! `hillslopeDiffuseCPU` (3872-3882), `centrifugalShear` (3926-3930),
//! `velocityErodeKernel` (3936-3994), `glacialKernel` (4198-4257),
//! `routeSediment` (4286-4307), `applyTidalSedimentation` (4324-4334) and
//! `coastalProcess`/`coastalProcessCPU` (4388-4424).
//!
//! `assert_eq!` on `f32`, no tolerance: every one of these is a pure
//! grid kernel with no RNG and no libm call outside `cartalith-jsmath`'s
//! own reproductions, so bit-exactness is the right bar.

use cartalith_erosion::{
    apply_tidal_sedimentation, centrifugal_shear, coastal_process, glacial_kernel,
    hillslope_diffuse, route_sediment, velocity_erode_kernel, CoastalParams, GlacialParams,
    VelocityParams,
};


